CREATE TABLE heros (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    hp_max REAL,
    hp_growth REAL,
    hp_start REAL,
    mp_max REAL,
    mp_growth REAL,
    mp_start REAL,
    attack_max REAL,
    attack_growth REAL,
    attack_start REAL,
    defense_max REAL,
    defense_growth REAL,
    defense_start REAL,
    speed REAL,
    power_rate REAL,
    magic_rate REAL,
    attack_range TEXT,
    role_main TEXT,
    role_assist TEXT,
    birthdate TEXT
);

